 	cell->next = NULL;
 	f->cells++;
 	spin_unlock_irqrestore(&f->lock, flags);

 	/* wakeup client */
 	if (waitqueue_active(&f->input_sleep))
 		wake_up(&f->input_sleep);

 	snd_use_lock_free(&f->use_lock);

 	return 0; /* success */

